using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using SolidWorks.Interop.sldworks;

public partial class Cad {
    class Hit {public string event_id;public int frame;public double time_s,volume_mm3;public string[] parts;}
    class BodyData {public IBody2 Body;public double[] Box;}
    class GeometryCache:IDisposable {
        public Dictionary<string,BodyData[]> Bodies=new Dictionary<string,BodyData[]>();
        public GeometryCache(IModelDoc2 doc){foreach(IComponent2 c in (object[])((IAssemblyDoc)doc).GetComponents(false))Bodies[c.Name2]=SolidBodies(c).Select(b=>{var copy=(IBody2)b.Copy();return new BodyData{Body=copy,Box=ExactBox(copy)};}).ToArray();}
        public void Dispose(){foreach(var a in Bodies.Values)foreach(var b in a)Release(b.Body);}
    }
    static double[] WorldBox(double[] local,double[] pose){var points=Enumerable.Range(0,8).Select(i=>ApplyPose(pose,new[]{local[(i&1)==0?0:3],local[(i&2)==0?1:4],local[(i&4)==0?2:5]},true)).ToArray();return Enumerable.Range(0,6).Select(i=>i<3?points.Min(p=>p[i])-1e-9:points.Max(p=>p[i-3])+1e-9).ToArray();}
    static bool BoxesMeet(double[] a,double[] b){return Enumerable.Range(0,3).All(j=>a[j]<=b[3+j]&&b[j]<=a[3+j]);}
    List<double> PairAt(GeometryCache cache,string a,string b,double[] pa,double[] pb){var hits=new List<double>();foreach(var ab in cache.Bodies[a])foreach(var bb in cache.Bodies[b])if(BoxesMeet(WorldBox(ab.Box,pa),WorldBox(bb.Box,pb)))hits.AddRange(PairRegions(ab.Body,pa,bb.Body,pb));return hits;}
    static string PairKey(IEnumerable<string> parts){return string.Join("|",parts.OrderBy(n=>n,StringComparer.Ordinal));}
    static double[] RelativePose(double[] a,double[] b){var values=new List<double>();for(int i=0;i<3;i++)for(int j=0;j<3;j++)values.Add(Enumerable.Range(0,3).Sum(k=>b[3*i+k]*a[3*j+k]));for(int j=0;j<3;j++)values.Add(Enumerable.Range(0,3).Sum(k=>(b[9+k]-a[9+k])*a[3*j+k]));values.Add(a[12]);values.Add(b[12]);return values.ToArray();}
    static Dictionary<string,double> Totals(IEnumerable<Hit> hits){return hits.GroupBy(h=>PairKey(h.parts)).ToDictionary(g=>g.Key,g=>g.Sum(h=>h.volume_mm3));}
    static void AtomicJson(string path,object value){AtomicMetadata.Write(path,Json.Serialize(value));}
    void Progress(string jobId,string stage,int completed,int total,string runId){if(string.IsNullOrEmpty(jobId))return;if(!System.Text.RegularExpressions.Regex.IsMatch(jobId,"^[a-f0-9]{32}$"))throw new Exception("INVALID_JOB_ID");AtomicJson(Path.Combine(Root,"runs","progress",jobId+".json"),new{job_id=jobId,stage=stage,completed=completed,total=total,run_id=runId,updated_at=(DateTime.UtcNow-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalSeconds});}
    Dictionary<string,double> NativePairTotals(IModelDoc2 doc,double threshold,string[] exclusions){var mgr=(IInterferenceDetectionMgr)((IAssemblyDoc)doc).InterferenceDetectionManager;var totals=new Dictionary<string,double>();try{mgr.TreatCoincidenceAsInterference=false;mgr.IgnoreHiddenBodies=false;var a=mgr.GetInterferences() as object[];if(a!=null)foreach(IInterference hit in a){string key=PairKey(((object[])hit.Components).Cast<IComponent2>().Select(c=>c.Name2));double v=hit.Volume*1e9;if(v>threshold&&!exclusions.Contains(key)){if(!totals.ContainsKey(key))totals[key]=0;totals[key]+=v;}}return totals;}finally{mgr.Done();}}
    public object FastCheck(string id,int frameStep,double threshold,string jobId){var r=GetRun(id);if(frameStep<1||frameStep>r.Times.Length||threshold<0||double.IsNaN(threshold)||double.IsInfinity(threshold))throw new Exception("INVALID_SAMPLING_OPTIONS");var s=new Scope(this,r.Path,r.Study);var hits=new List<Hit>();var exclusions=r.Assembly=="clear"||r.Assembly=="obstacle"||r.Assembly=="parameter_trial"?new[]{PairKey(new[]{"base-1","crank-1"}),PairKey(new[]{"crank-1","rod-1"}),PairKey(new[]{"rod-1","slider-1"})}:new string[0];
        var indices=Enumerable.Range(0,r.Times.Length).Where(i=>i%frameStep==0).Concat(new[]{r.Times.Length-1}).Distinct().OrderBy(i=>i).ToArray();var audits=indices.Where(i=>i==0||i==indices[indices.Length/2]||i==r.Times.Length-1).ToArray();double maxAuditError=0,maxPoseDelta=0;int cacheHits=0;var timer=Stopwatch.StartNew();double geometrySeconds=0,auditSeconds=0;
        string fallbackReason=null;try{ValidateRun(r,s);using(var cache=new GeometryCache(s.Doc)){var names=cache.Bodies.Keys.OrderBy(n=>n,StringComparer.Ordinal).ToArray();var staticCache=new Dictionary<string,List<double>>();
            s.Study.SetTime(0);Application.DoEvents();var staticNative=NativePairTotals(s.Doc,threshold,exclusions);
            foreach(string a in names)foreach(string b in names.Where(n=>StringComparer.Ordinal.Compare(n,a)>0)){string key=PairKey(new[]{a,b});var relative=RelativePose(r.Poses[a][0],r.Poses[b][0]);bool rigid=Enumerable.Range(0,r.Times.Length).All(i=>RelativePose(r.Poses[a][i],r.Poses[b][i]).Zip(relative,(x,y)=>Math.Abs(x-y)).Max()<1e-9);if(rigid)staticCache[key]=staticNative.ContainsKey(key)?new List<double>{staticNative[key]}:new List<double>();}
            for(int index=0;index<indices.Length;index++){int i=indices[index];s.EnsureActive();Progress(jobId,"native_body_scan",index,indices.Length,id);var frameHits=new List<Hit>();var clock=Stopwatch.StartNew();
                for(int x=0;x<names.Length;x++)for(int y=x+1;y<names.Length;y++){string a=names[x],b=names[y],key=PairKey(new[]{a,b});if(exclusions.Contains(key))continue;List<double> volumes;if(staticCache.TryGetValue(key,out volumes))cacheHits++;else{volumes=PairAt(cache,a,b,r.Poses[a][i],r.Poses[b][i]);}
                    foreach(double v in volumes)if(v>threshold)frameHits.Add(new Hit{frame=i,time_s=r.Times[i],parts=new[]{a,b},volume_mm3=v});}
                geometrySeconds+=clock.Elapsed.TotalSeconds;
                if(audits.Contains(i)){clock.Restart();s.Study.SetTime(Argument(r.Times[i],r.Duration));Application.DoEvents();var actual=Transforms(s.Doc);double delta=actual.Max(p=>p.Value.Zip(r.Poses[p.Key][i],(a,b)=>Math.Abs(a-b)).Max());maxPoseDelta=Math.Max(maxPoseDelta,delta);if(delta>1e-7)throw new Exception("POSE_MISMATCH");var native=NativePairTotals(s.Doc,threshold,exclusions);var fast=Totals(frameHits);foreach(string pair in native.Keys.Concat(fast.Keys).Distinct()){double a=native.ContainsKey(pair)?native[pair]:0,b=fast.ContainsKey(pair)?fast[pair]:0;double error=Math.Abs(a-b);maxAuditError=Math.Max(maxAuditError,error);if(error>Math.Max(.0005,Math.Abs(a)*1e-7))throw new Exception("ENGINE_CROSSCHECK_FAILED frame="+i+" pair="+pair+" error_mm3="+error);}auditSeconds+=clock.Elapsed.TotalSeconds;}
                foreach(var h in frameHits){h.event_id="event_"+hits.Count;hits.Add(h);}Progress(jobId,"native_body_scan",index+1,indices.Length,id);
            }}ValidateRun(r,s);
        }catch(Exception e){if(!e.Message.StartsWith("ENGINE_CROSSCHECK_FAILED"))throw;fallbackReason=e.Message;}finally{s.Dispose();}if(!s.Restored)throw new Exception("RESTORATION_FAILED");
        if(fallbackReason!=null){double candidateSeconds=timer.Elapsed.TotalSeconds;AtomicJson(Path.Combine(r.Directory,"hybrid-rejected.json"),new{reason=fallbackReason,elapsed_s=candidateSeconds,maximum_pair_volume_error_mm3=maxAuditError,assertion="inconclusive",restoration_status="restored"});var fallback=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(CheckMotion(id,frameStep,threshold)));fallback["engine"]="native_manager_fallback";fallback["candidate_failure"]=fallbackReason;fallback["candidate_elapsed_s"]=candidateSeconds;fallback["elapsed_s"]=timer.Elapsed.TotalSeconds;return fallback;}
        string path=Path.Combine(r.Directory,"interference-fast-step-"+frameStep+".json");var report=new{run_id=id,assembly=r.Assembly,model_path=r.Path,study=r.Study,fingerprint=r.Fingerprint,engine="native_static_cache_and_temporary_body_intersection",assertion=hits.Count==0?"pass":"fail",claim="discrete_sampled_frames_only",continuous_collision=false,sampling_source="validated_solver_output_transform_cache",checked_frames=indices.Length,total_output_frames=r.Times.Length,checked_frame_indices=indices,maximum_time_step_s=indices.Skip(1).Zip(indices,(a,b)=>(double)(a-b)/r.Fps).DefaultIfEmpty(0).Max(),volume_threshold_mm3=threshold,excluded_joint_pairs=exclusions,events=hits,first_detected_event=hits.FirstOrDefault(),native_replay_audit_frames=audits,maximum_engine_pair_volume_error_mm3=maxAuditError,maximum_pose_difference=maxPoseDelta,restoration_status="restored",timings=new{total_s=timer.Elapsed.TotalSeconds,geometry_s=geometrySeconds,audit_s=auditSeconds,stationary_pair_cache_hits=cacheHits},report_path=path};File.WriteAllText(path,Json.Serialize(report));reports[id]=path;Progress(jobId,"completed",indices.Length,indices.Length,id);return new{run_id=id,assertion=hits.Count==0?"pass":"fail",claim="discrete_sampled_frames_only",checked_frames=indices.Length,event_count=hits.Count,engine="native_static_cache_and_temporary_body_intersection",elapsed_s=timer.Elapsed.TotalSeconds,maximum_engine_pair_volume_error_mm3=maxAuditError,restoration_status="restored",report_path=path};
    }
    public object DiagnosePhase(){var s=new Scope(this,PumpPath,"齿轮泵_30rpm");var trials=new List<object>();double bestPhase=0,bestPeak=double.PositiveInfinity;var timer=Stopwatch.StartNew();string dir=Path.Combine(Root,"runs","v03-diagnostics");Directory.CreateDirectory(dir);
        try{Fingerprint(s.Doc,s.DocumentPath);s.Study.SetTime(0);Application.DoEvents();var a=ResolvePump(s.Doc,"driving_gear");var b=ResolvePump(s.Doc,"driven_gear");var ab=SolidBodies(a)[0];var bb=SolidBodies(b)[0];var pa=(double[])a.Transform2.ArrayData;var pb=(double[])b.Transform2.ArrayData;
            var af=PumpAxis(a,.083258518,.006402892);var bf=PumpAxis(b,.083258518,.041402892);var ac=WorldPoint(a,((double[])((ISurface)af.GetSurface()).CylinderParams).Take(3).ToArray());var bc=WorldPoint(b,((double[])((ISurface)bf.GetSurface()).CylinderParams).Take(3).ToArray());
            int teeth=Faces(a).Count(f=>{var surface=(ISurface)f.GetSurface();return surface.IsCylinder()&&Math.Abs(((double[])surface.CylinderParams)[6]-.02)<1e-8;});if(teeth!=14)throw new Exception("UNEXPECTED_TOOTH_COUNT "+teeth);double pitch=360.0/teeth;
            using(var csv=new StreamWriter(Path.Combine(dir,"phase-curves.csv"))){csv.WriteLine("trial,phase_offset_deg,frame,driving_angle_deg,gear_pair_total_mm3");
                var candidates=Enumerable.Range(0,9).Select(i=>i*pitch/8).ToList();
                for(int trial=0;trial<candidates.Count&&trial<16;trial++){double phase=candidates[trial],peak=0,sum=0;int hitFrames=0;
                    for(int i=0;i<=60;i++){s.EnsureActive();double theta=i*6.0;var v=PairRegions(ab,RotateWorld(pa,ac[0],ac[1],theta),bb,RotateWorld(pb,bc[0],bc[1],phase-theta));double volume=v.Where(x=>x>.001).Sum();peak=Math.Max(peak,volume);sum+=volume;if(volume>.001)hitFrames++;csv.WriteLine(string.Join(",",new[]{(double)trial,phase,i,theta,volume}.Select(x=>x.ToString("R",System.Globalization.CultureInfo.InvariantCulture))));}
                    csv.Flush();trials.Add(new{trial=trial,phase_offset_deg=phase,frames=61,maximum_total_volume_mm3=peak,mean_total_volume_mm3=sum/61,collision_frames=hitFrames});if(peak<bestPeak){bestPeak=peak;bestPhase=phase;}
                    Log("PHASE_TRIAL "+trial+" phase="+phase+" peak="+peak);File.WriteAllText(Path.Combine(dir,"phase-progress.json"),Json.Serialize(new{completed_trials=trials,best_phase_deg=bestPhase,best_peak_mm3=bestPeak,elapsed_s=timer.Elapsed.TotalSeconds}));
                    if(trial==8){double center=bestPhase;for(int j=-3;j<=3;j++)candidates.Add((center+j*pitch/32+pitch)%pitch);}
                    if(timer.Elapsed.TotalSeconds>180)break;
                }
            }
        }finally{s.Dispose();}if(!s.Restored)throw new Exception("RESTORATION_FAILED");var report=new{scope="gear_pair_only_on_temporary_body_copies",model_mutated=false,method="native_body_intersection_with_world_rotation",trials=trials,best_phase_deg=bestPhase,best_peak_mm3=bestPeak,assertion=bestPeak<=.001?"pass":"fail",claim="61_discrete_angular_samples_per_candidate",stop_reason=timer.Elapsed.TotalSeconds>180?"time_budget":"trial_budget",elapsed_s=timer.Elapsed.TotalSeconds,restoration_status="restored",curves_csv=Path.Combine(dir,"phase-curves.csv")};File.WriteAllText(Path.Combine(dir,"phase-search.json"),Json.Serialize(report));return report;
    }
    static IBody2[] SolidBodies(IComponent2 c){object info;var a=c.GetBodies3(0,out info) as object[];if(a==null||a.Length==0)throw new Exception("COMPONENT_BODIES_UNAVAILABLE "+c.Name2);var bodies=a.Cast<IBody2>().ToArray();foreach(var b in bodies){var faults=b.Check3;if(faults!=null&&faults.Count>0)throw new Exception("INVALID_SOLID_BODY "+c.Name2+" "+faults.Count);}return bodies;}
    static double[] ExactBox(IBody2 b){var box=new double[6];for(int j=0;j<3;j++){var d=new double[3];d[j]=1;double x,y,z;if(!b.GetExtremePoint(d[0],d[1],d[2],out x,out y,out z))throw new Exception("BOUNDING_BOX_FAILED");box[3+j]=new[]{x,y,z}[j];d[j]=-1;if(!b.GetExtremePoint(d[0],d[1],d[2],out x,out y,out z))throw new Exception("BOUNDING_BOX_FAILED");box[j]=new[]{x,y,z}[j];}return box;}
    static double[] RotateWorld(double[] pose,double cx,double cy,double degrees){double a=degrees*Math.PI/180,c=Math.Cos(a),s=Math.Sin(a);var p=(double[])pose.Clone();for(int j=0;j<3;j++){p[j*3]=c*pose[j*3]-s*pose[j*3+1];p[j*3+1]=s*pose[j*3]+c*pose[j*3+1];}p[9]=cx+c*(pose[9]-cx)-s*(pose[10]-cy);p[10]=cy+s*(pose[9]-cx)+c*(pose[10]-cy);return p;}
    static double Volume(IBody2 b){var m=(double[])b.GetMassProperties(1);if(m==null||m.Length<4||double.IsNaN(m[3])||m[3]<0)throw new Exception("BODY_VOLUME_UNAVAILABLE");return m[3]*1e9;}
    IBody2 Positioned(IBody2 b,double[] pose){var copy=(IBody2)b.Copy();if(copy==null||!copy.ApplyTransform((MathTransform)((IMathUtility)Sw.GetMathUtility()).CreateTransform(pose)))throw new Exception("TEMP_BODY_TRANSFORM_FAILED");return copy;}
    static void Release(object o){if(o!=null&&Marshal.IsComObject(o))Marshal.ReleaseComObject(o);}
    double[] PairRegions(IBody2 a,double[] pa,IBody2 b,double[] pb){IBody2 ac=null,bc=null;object bodies=null;
        try{ac=Positioned(a,pa);bc=Positioned(b,pb);int error; bodies=ac.Operations2(15901,bc,out error);var hits=bodies as object[];if(error==5||error==6||error==1067)return new double[0];if(error!=0)throw new Exception("BODY_INTERSECTION_UNCONFIRMED "+error);return hits==null?new double[0]:hits.Cast<IBody2>().Select(Volume).ToArray();}
        finally{if(bodies is object[])foreach(var body in (object[])bodies)Release(body);Release(ac);Release(bc);}
    }
    public object ProbeAdvanced(){var s=new Scope(this,PumpPath,"齿轮泵_30rpm");object result=null;
        try{s.Study.SetTime(0);Application.DoEvents();var gears=new List<object>();var refs=new Dictionary<string,IComponent2>();
            foreach(string role in new[]{"driving_gear","driven_gear"}){var c=ResolvePump(s.Doc,role);refs[role]=c;var faces=new List<object>();foreach(var f in Faces(c)){var surf=(ISurface)f.GetSurface();faces.Add(new{kind=surf.IsCylinder()?"cylinder":surf.IsPlane()?"plane":"other",parameters=surf.IsCylinder()?(double[])surf.CylinderParams:surf.IsPlane()?(double[])surf.PlaneParams:null,area_m2=f.GetArea()});}
                var part=(IModelDoc2)c.GetModelDoc2();gears.Add(new{role=role,instance=c.Name2,configuration=c.ReferencedConfiguration,toolbox_part_type=part.Extension.ToolboxPartType,pose=(double[])c.Transform2.ArrayData,body_boxes=SolidBodies(c).Select(ExactBox).ToArray(),faces=faces});}
            string preDir=Path.Combine(Root,"runs","v03-diagnostics");Directory.CreateDirectory(preDir);File.WriteAllText(Path.Combine(preDir,"geometry-only.json"),Json.Serialize(gears));
            var a=refs["driving_gear"];var b=refs["driven_gear"];var watch=Stopwatch.StartNew();Log("PAIR_GEAR");var volumes=PairRegions(SolidBodies(a)[0],(double[])a.Transform2.ArrayData,SolidBodies(b)[0],(double[])b.Transform2.ArrayData);watch.Stop();
            var modeler=(IModeler)Sw.GetModeler();var cube1=(IBody2)modeler.CreateBodyFromBox3(new[]{0.0,0,0,0,0,1,.02,.02,.02});var cube2=(IBody2)cube1.Copy();var witnesses=new List<object>();
            foreach(double x in new[]{0.0,.01,.02,.03}){Log("PAIR_CUBE offset="+x);var hits=PairRegions(cube1,Pose(0,0,0,0),cube2,Pose(x,0,0,0));double expected=x==0?8000:x==.01?4000:0;if(Math.Abs(hits.Sum()-expected)>1e-5)throw new Exception("BOOLEAN_WITNESS_FAILED");witnesses.Add(new{offset_x_m=x,regions=hits,total_mm3=hits.Sum(),expected_mm3=expected});}Release(cube1);Release(cube2);
            result=new{process_id=Sw.GetProcessID(),gears=gears,gear_pair_regions_mm3=volumes,gear_pair_total_mm3=volumes.Sum(),pair_seconds=watch.Elapsed.TotalSeconds,witnesses=witnesses};
        }finally{s.Dispose();}if(!s.Restored)throw new Exception("RESTORATION_FAILED");string dir=Path.Combine(Root,"runs","v03-diagnostics");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"geometry-probe.json"),Json.Serialize(result));return result;
    }
}
